def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    markers = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 1]
    lines = set()
    for i, (r, c) in enumerate(markers):
        for rr, cc in markers[i + 1:]:
            if r == rr and {c, cc} == {0, w - 1}:
                lines.update((r, x) for x in range(w))
            if c == cc and {r, rr} == {0, h - 1}:
                lines.update((y, c) for y in range(h))
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and out[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if any(cell in lines for cell in component):
                for y, x in component:
                    out[y][x] = 1
    for r, c in lines:
        out[r][c] = 1
    return out
